export const originAreas={'Broderick House':[52.4710,-1.9130],'Selly Oak':[52.4415,-1.9350],'Birmingham City Centre':[52.4775,-1.8990],Harborne:[52.4590,-1.9505],Edgbaston:[52.4620,-1.9230],'The Vale':[52.4625,-1.9335],'Pritchatts Park Village':[52.4555,-1.9375]};
const distance=(a,b)=>Math.hypot((a[0]-b[0])*111320,(a[1]-b[1])*67800);
export function suggestBusOrigin(patterns,area){const origin=originAreas[area];if(!origin)return null;let best=null;for(const p of patterns)for(let end=1;end<p.stops.length;end++){const target=p.stops[end];if(!['University North Gate','University Station','School of Education'].includes(target.name))continue;for(let start=0;start<end;start++){const stop=p.stops[start],walk=distance(origin,[stop.lat,stop.lon]),score=walk+distance([target.lat,target.lon],[52.4508,-1.9305]);if(walk>1500)continue;if(!best||score<best.score)best={pattern:p.id,board:stop.id,alight:target.id,walk:Math.round(walk),score};}}return best;}
